mapper.insert:
        
            /* 공통 시퀀스 채번 함수 사용 */
            SELECT fn_get_dynamic_seq('utb_search_condition') AS conditionSeq
        

        INSERT INTO "MP_IPMS_PA".utb_search_condition (
        condition_seq
        , user_info_seq
        , menu_code
        , condition_name
        , search_options
        , date_filters
        , text_filters
        , use_yn
        , del_yn
        , create_user
        , create_at
        , update_user
        , update_at
        ) VALUES (
        #{conditionSeq}
        , #{userInfoSeq}
        , #{menuCode}
        , #{conditionName}
        , #{searchOptions}
        , #{dateFilters}
        , #{textFilters}
        , COALESCE(#{useYn}, 'Y')
        , 'N'
        , #{createUser}
        , CURRENT_TIMESTAMP
        , #{updateUser}
        , CURRENT_TIMESTAMP
        )
